const LOGIN="<!doctype html><meta charset=\"utf-8\"><title>Private reviewer sign-in</title><style>body{font:18px system-ui;max-width:440px;margin:12vh auto;background:#0c1423;color:#e5edfa}input,button{box-sizing:border-box;padding:14px;width:100%;margin:10px 0}small{color:#adbed4}</style><h1>Private reviewer sign-in</h1><p>Synthetic evidence test. Only the enrolled reviewer can enter.</p><form id=\"f\"><label>Username<input name=\"username\" autocomplete=\"username\" required></label><label>Password<input name=\"password\" type=\"password\" autocomplete=\"current-password\" required></label><button>Sign in</button></form><p id=\"r\"></p><small>No claimant data. No insurance decision or external action.</small><script>f.onsubmit=async e=>{e.preventDefault();const q=await fetch('/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))});if(q.ok)location.href='/';else r.textContent='Sign-in failed or reviewer not enrolled.';}</script>\n";
const REVIEW="<!doctype html><html><head><meta charset=\"utf-8\"><title>Private evidence review</title><style>body{font:17px system-ui;max-width:1150px;margin:40px auto;padding:24px;background:#0c1423;color:#e5edfa}article,section{background:#141f32;border:1px solid #31425a;border-radius:10px;padding:22px;margin:18px 0}h1{font-size:30px}p{line-height:1.5}img{max-width:100%;max-height:600px}a{color:#79cff1}button{padding:14px;background:#147366;color:white;border:0;border-radius:6px}small{overflow-wrap:anywhere;color:#adbed4}</style></head><body><h1>Private synthetic evidence review</h1><p id=\"who\"></p><p>No claim decision, payout, external message or legal action is authorised here.</p><section id=\"report\"></section><main id=\"images\"></main><section><h2>Reviewer decision</h2><p>The action below records only that you have reviewed this exact synthetic address report for internal demonstration. It does not approve an insurance claim or external use.</p><button id=\"approve\">I reviewed this synthetic report</button><p id=\"result\"></p></section><script>const safe=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));let state;async function load(){const r=await fetch('/api/state');if(r.status===401){location.href='/login';return;}state=await r.json();who.textContent='Signed in as '+state.principal;report.innerHTML='<h2>'+safe(state.report.claim_ref)+'</h2>'+Object.entries(state.report.findings).map(([k,v])=>'<p><b>'+safe(k.replaceAll('_',' '))+':</b> '+safe(Array.isArray(v)?v.join(' · '):v)+'</p>').join('');images.innerHTML=state.report.captures.map(c=>'<article><h2>'+safe(c.file)+'</h2><img src=\"/images/'+safe(c.vault_evidence_id)+'\"><p><a href=\"'+safe(c.url)+'\" rel=\"noreferrer\" target=\"_blank\">Recorded Maps source</a></p><small>Capture '+safe(c.captured_at)+' · '+safe(c.sha256)+'</small></article>').join('');}approve.onclick=async()=>{approve.disabled=true;try{const a=await fetch('/api/approve',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':state.csrf},body:JSON.stringify({digest:state.action.digest})});const j=await a.json();if(!a.ok)throw Error(j.error);const r=await fetch('/api/record-review',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':state.csrf},body:JSON.stringify({token:j.token})});const out=await r.json();result.textContent=r.ok?'Internal review recorded for '+out.principal+'. No external action.':'Not recorded: '+out.error;}catch(e){result.textContent=e.message;}finally{approve.disabled=false;}};load();</script></body></html>\n";
